import json
from pathlib import Path

import pytest
from llmxive_toolkit import paths

# Load the manifest generated by the download script
@pytest.fixture(scope="module")
def manifest():
    manifest_path = paths.data("raw", "openneuro", "ds000246", "manifest.json")
    assert manifest_path.is_file(), "manifest.json not found"
    with manifest_path.open() as f:
        return json.load(f)

def test_at_least_20_subjects(manifest):
    subjects = {entry["subject_id"] for entry in manifest}
    assert len(subjects) >= 20, f"Expected >=20 subjects, found {len(subjects)}"

def test_each_subject_has_improv_and_scripted(manifest):
    runs_by_subject = {}
    for entry in manifest:
        runs_by_subject.setdefault(entry["subject_id"], set()).add(entry["run_label"])
    missing = [
        sid for sid, runs in runs_by_subject.items()
        if not {"Improv", "Scripted"}.issubset(runs)
    ]
    assert not missing, f"Subjects missing runs: {missing}"

def test_checksums_file_exists():
    checksums_path = paths.data("raw", "checksums.json")
    assert checksums_path.is_file(), "checksums.json not found"

def test_checksums_match_files(manifest):
    checksums_path = paths.data("raw", "checksums.json")
    with checksums_path.open() as f:
        checksums = json.load(f)
    for entry in manifest:
        filename = f"{entry['subject_id']}_{entry['run_label']}.nii.gz"
        assert filename in checksums, f"Checksum missing for {filename}"